static void require(bool value,const char* message){if(!value)throw std::runtime_error(message);}
static Features measured(double timestamp,double ear=.3){Features f;f.timestamp=timestamp;f.facePresent=true;f.eyesVisible=true;f.mouthVisible=true;f.poseReliable=true;f.leftEar=f.rightEar=ear;f.mar=.04;f.reason="Scripted test features";return f;}
static Decision advance(Temporal& temporal,double& clock,double seconds,double ear=.3,bool visible=true,double mar=.04,double pitch=0,int rate=30){Decision d;for(int i=0;i<(int)(seconds*rate);++i){clock+=1./rate;Features f=measured(clock,ear);f.eyesVisible=visible;f.mar=mar;f.pitch=pitch;d=temporal.update(f);}return d;}
int tests(const std::string& root){int count=0;Settings s;Temporal normal(s);double clock=-1./30;Decision d=advance(normal,clock,6);require(d.calibrated&&d.state=="MONITORING"&&!d.alarm,"Personal open-eye calibration");++count;
 d=advance(normal,clock,.16,.10);require(!d.alarm,"Normal blink must not trigger prolonged closure alarm");++count;advance(normal,clock,2);d=advance(normal,clock,2,.10);require(d.alarm&&d.closureSeconds>=1.5,"Sustained bilateral eye closure alarm");++count;
 d=advance(normal,clock,1,.1,false);require(d.alarm&&d.state=="DROWSINESS_ALERT","Poor view must not silently clear an existing alert");++count;d=advance(normal,clock,3);require(!d.alarm,"Sustained usable open-eye recovery");++count;
 Temporal unknown(s);clock=-1./30;d=advance(unknown,clock,5,.1,false);require(d.state=="UNABLE_TO_ASSESS"&&!d.alarm&&d.observationFault,"Unobservable eyes must never claim normal monitoring or count as closed eyes");++count;
 Temporal gap(s);Features f=measured(0,.1);gap.update(f);f.timestamp=2;d=gap.update(f);require(!d.alarm&&d.closureSeconds==0&&d.validSeconds==0,"Inference gaps must not be integrated as closed-eye evidence");++count;
 Temporal aggregate(s);clock=-1./30;for(int i=0;i<16;++i){advance(aggregate,clock,1.2);d=advance(aggregate,clock,.8,.1);}require(d.alarm&&d.perclos>.3&&d.validSeconds>=10,"Time-weighted PERCLOS alarm");++count;
 Temporal coverage(s);clock=-1./30;advance(coverage,clock,4);advance(coverage,clock,1,.1);d=advance(coverage,clock,25,.1,false);require(!d.alarm&&d.coverage<.3,"Missing observation coverage must not inflate PERCLOS evidence");++count;
 Temporal slow(s),fast(s);double a=-1./15,b=-1./60;Decision da=advance(slow,a,2,.1,true,.04,0,15),db=advance(fast,b,2,.1,true,.04,0,60);require(da.alarm&&db.alarm&&std::abs(da.closureSeconds-db.closureSeconds)<.08,"Closure timing must be frame-rate independent");++count;
 Temporal closedStart(s);clock=-1./30;d=advance(closedStart,clock,6,.1);require(!d.calibrated&&d.alarm,"Closed eyes at startup must not become an open-eye baseline");++count;
 Temporal yawns(s);clock=-1./30;advance(yawns,clock,6);advance(yawns,clock,1.4,.3,true,.7);advance(yawns,clock,.4);d=advance(yawns,clock,1.4,.3,true,.7);require(d.yawns==2&&!d.alarm,"Yawning alone is insufficient for drowsiness alert");++count;
 Temporal fused(s);clock=-1./30;advance(fused,clock,6);advance(fused,clock,1.4,.3,true,.7,20);advance(fused,clock,.4);d=advance(fused,clock,1.4,.3,true,.7,20);require(d.yawns==2&&d.nods==2&&d.alarm,"Repeated yawns plus nods provide a separate cue path");++count;
 Temporal angles(s);f=measured(0);f.yaw=65;d=angles.update(f);require(d.state=="UNABLE_TO_ASSESS","Unsupported face angles must not claim observable eyes");++count;
 Temporal invalid(s);f=measured(0);f.leftEar=std::numeric_limits<double>::quiet_NaN();d=invalid.update(f);require(d.state=="UNABLE_TO_ASSESS","Invalid measurements must fail to unknown");++count;
 bool rejected=false;try{invalid.update(f);}catch(const std::invalid_argument&){rejected=true;}require(rejected,"Duplicate timestamps rejected");++count;
 Settings bad=s;bad.irWhite=bad.irBlack;rejected=false;try{validateSettings(bad);}catch(const std::invalid_argument&){rejected=true;}require(rejected,"Invalid IR range rejected");++count;
 bad=s;bad.perclosAlarm=std::numeric_limits<double>::quiet_NaN();rejected=false;try{validateSettings(bad);}catch(const std::invalid_argument&){rejected=true;}require(rejected,"Nonfinite configuration rejected");++count;

 Settings raw=s;raw.irBlack=1000;raw.irWhite=5000;uint16_t sensor[2]={1000,5000};Image converted=fromY16(sensor,2,1,4,raw.irBlack,raw.irWhite);require(converted.row(0)[0]==0&&converted.row(0)[3]==255,"Y16 fixed-range conversion");++count;
 Image mono(30,20,80);converted=cameraPixels(mono,s);require(converted.width==30&&converted.row(0)[0]==80,"Infrared grayscale conversion");++count;
 Image tiny(1,1);overlay(tiny,Features(),Decision(),30);++count;require(jsonString("a\"\n")=="\"a\\\"\\u000a\"","JSON controls escaped");++count;
 std::vector<Point> points(468);int ids[6]={0,1,2,3,4,5};points[0]={0,0};points[1]={2,2};points[2]={8,2};points[3]={10,0};points[4]={8,-2};points[5]={2,-2};require(std::abs(eyeRatio(points,ids)-.4)<1e-6,"Eye aspect geometry");++count;
 Temporal subject(s);clock=-1./30;advance(subject,clock,6);f=measured(clock+1./30);f.identityChanged=true;d=subject.update(f);require(!d.calibrated&&d.state=="CALIBRATING","New subject resets calibration/history");++count;
 auto synthetic=poseFixture(15,-20,12,640,480);double pitch=0,yaw=0,roll=0;require(estimatePose(synthetic,640,480,{150,80,300,320},pitch,yaw,roll)&&std::abs(pitch-15)<.1&&std::abs(yaw+20)<.1&&std::abs(roll-12)<.1,"Canonical pose solver recovers synthetic 3D rotation");++count;
 synthetic[1].x=std::numeric_limits<double>::quiet_NaN();require(!estimatePose(synthetic,640,480,{150,80,300,320},pitch,yaw,roll),"Nonfinite pose observations rejected");++count;
 Image rgb(4,4);fillRect(rgb,{0,0,4,4},10,20,30);require(grayscale(rgb).row(0)[0]==22,"Native BGR grayscale weights");++count;Image small=resizeImage(rgb,2,2);require(small.row(1)[3]==10&&small.width==2,"Native bilinear resize");++count;
 bool bounds=false;try{cropImage(rgb,{-1,0,3,3});}catch(const std::invalid_argument&){bounds=true;}require(bounds,"Out-of-bounds crop rejected");++count;
 s.models=root+"models";s.infrared=false;Vision vision(s);Image photo=loadImage(root+"testdata/face.png");require(!photo.empty(),"NASA photo fixture");++count;Image face=resizeImage(cropImage(photo,{100,0,320,240}),640,480);Features actual=vision.analyze(face,0);std::cout<<"Face confidence="<<actual.faceConfidence<<" mesh="<<actual.meshConfidence<<" EAR="<<actual.leftEar<<","<<actual.rightEar<<" pose="<<actual.pitch<<","<<actual.yaw<<" eyes="<<actual.eyesVisible<<" reason="<<actual.reason<<'\n';require(actual.facePresent&&actual.landmarks.size()==468&&actual.eyesVisible,"Actual neural face and landmark inference");++count;
 Image annotation=face;Decision annotationDecision;annotationDecision.state=actual.eyesVisible?"CALIBRATING":"UNABLE_TO_ASSESS";overlay(annotation,actual,annotationDecision,0);saveImage(root+"tests/model_fixture.jpg",annotation);
 Features blank=vision.analyze(Image(640,480),.1);require(!blank.eyesVisible,"Blank frame provides no eye evidence");++count;
 Settings opaque=s;opaque.eyewear="opaque";Vision obscured(opaque);require(!obscured.analyze(face,0).eyesVisible,"Opaque-eyewear override disables eye-state claims");++count;
 Image masked=face;int eyeY=(int)((actual.landmarks[33].y+actual.landmarks[263].y)*.5);fillRect(masked,{actual.face.x,std::max(0,eyeY-30),actual.face.width,60},0,0,0);require(!vision.analyze(masked,.2).eyesVisible,"Black eye mask must be unknown");++count;
 Settings ir=s;ir.infrared=true;Vision irVision(ir);Features irFace=irVision.analyze(cameraPixels(face,ir),0);require(irFace.facePresent&&irFace.landmarks.size()==468&&irFace.eyesVisible,"Grayscale IR-style inference");++count;
 Image half=resizeImage(face,320,240),dual(640,480);paste(dual,half,0,120);paste(dual,half,320,120);Features multiple=vision.analyze(dual,.3);require(!multiple.eyesVisible&&multiple.reason.find("Multiple faces")!=std::string::npos,"Multiple detected faces remain unknown");++count;
 Settings roiSettings=s;roiSettings.roi={0,120,320,240};Vision roiVision(roiSettings);Features selected=roiVision.analyze(dual,0);require(selected.facePresent&&selected.landmarks.size()==468,"Monitoring ROI isolates one subject without sampling its padding from outside the ROI");++count;
 Image compressed=decodeImage(encodeJPEG(cameraPixels(dual,ir)));Features compressedMultiple=irVision.analyze(compressed,.1);require(!compressedMultiple.eyesVisible&&compressedMultiple.reason.find("Multiple faces")!=std::string::npos,"Compressed grayscale multiple-face ambiguity");++count;
 require(!vision.analyze(dimImage(face,.10,2),.4).eyesVisible,"Raw darkness cannot be enhanced into usable evidence");++count;require(!vision.analyze(blurImage(face,25),.5).eyesVisible,"Severe blur fails observability");++count;
 Features rotated=vision.analyze(rotateImage(face,20),.6);require(rotated.facePresent&&rotated.landmarks.size()==468,"Rotated face inference");++count;
 Image jpeg=decodeImage(encodeJPEG(face));require(jpeg.width==640&&jpeg.height==480,"WIC JPEG round trip");++count;
 VideoWriter avi(root+"tests/native_roundtrip.avi",64,48,30);for(int i=0;i<5;++i)avi.write(Image(64,48,(unsigned char)(i*40)));avi.close();VideoSource decoded(root+"tests/native_roundtrip.avi",64,48,30,false,"",0,65535);Image frame;int decodedFrames=0;while(decoded.read(frame)){require(frame.width==64&&frame.height==48,"AVI round-trip dimensions");++decodedFrames;}require(decodedFrames==5&&std::abs(decoded.fps()-30)<.01,"Native MJPEG AVI frame/index round trip");++count;
 VideoSource independent(root+"tests/native_roundtrip.avi",64,48,30,false,"",0,65535,false);decodedFrames=0;while(independent.read(frame)){require(frame.width==64&&frame.height==48&&std::abs(int(frame.row(20)[30])-decodedFrames*40)<4,"Independent Media Foundation AVI pixel decode");++decodedFrames;}require(decodedFrames==5,"Independent Windows decoder validates native AVI headers and frames");++count;
 Model model(s.models+"/face_detector.onnx");Tensor invalidTensor;invalidTensor.shape={1,3,128,128};bool badTensor=false;try{model.forward(invalidTensor);}catch(const std::invalid_argument&){badTensor=true;}require(badTensor,"Tensor shape/data mismatch rejected");++count;
 std::vector<double> times;for(int i=0;i<60;++i){auto start=std::chrono::steady_clock::now();vision.analyze(face,1.+i/30.);times.push_back(std::chrono::duration<double,std::milli>(std::chrono::steady_clock::now()-start).count());}std::sort(times.begin(),times.end());double sum=0;for(double x:times)sum+=x;std::ofstream report(root+"tests/self_test_last.json");report<<"{\"status\":\"passed\",\"checks\":"<<count<<",\"actual_model_inference\":true,\"cpu_inference_mean_ms\":"<<sum/times.size()<<",\"cpu_inference_p95_ms\":"<<times[(size_t)(.95*(times.size()-1))]<<",\"physical_ir_camera_tested\":false,\"clinical_drowsiness_accuracy_measured\":false,\"eyewear_angle_accuracy_measured\":false}\n";std::cout<<"PASS "<<count<<" checks | CPU mean="<<sum/times.size()<<" ms p95="<<times[(size_t)(.95*(times.size()-1))]<<" ms\n";return 0;
}
static void verifyVideo(const std::string& path,int expected,int width,int height){VideoSource video(path,width,height,30,false,"",0,65535);Image image;int count=0;while(video.read(image)){if(image.width!=width||image.height!=height)throw std::runtime_error("Video dimensions changed");++count;}require(count==expected&&std::abs(video.fps()-30)<.01,"Recorded video frame count/rate");}
static void ellipse(Image& image,Point centre,Point radius,unsigned char b,unsigned char g,unsigned char r){for(int i=0;i<720;++i){double angle=i*3.141592653589793/360;drawPoint(image,{centre.x+radius.x*std::cos(angle),centre.y+radius.y*std::sin(angle)},b,g,r);}}
int demo(const std::string& root,bool directml){Settings s;s.models=root+"models";s.directml=directml;Vision vision(s);Temporal actual(s);Image photo=loadImage(root+"testdata/face.png"),base=resizeImage(cropImage(photo,{100,0,320,240}),640,480);VideoWriter camera(root+"testdata/vision_demo_input.avi",640,480,30),observed(root+"output/vision_demo.avi",640,480,30);Features baseline=vision.analyze(base,0);
 for(int frame=0;frame<360;++frame){Image image=base;std::string condition="VISIBLE PHOTO";if(frame>=90&&frame<150){image=grayscale(image);condition="GRAYSCALE SIMULATION - NOT A REAL IR CAMERA";}else if(frame>=150&&frame<210){image=dimImage(image,.10,2);condition="DIM IMAGE STRESS TEST";}else if(frame>=210&&frame<270){if(baseline.landmarks.size()==468){int y=(int)((baseline.landmarks[33].y+baseline.landmarks[263].y)*.5);fillRect(image,{baseline.face.x,std::max(0,y-30),baseline.face.width,60},0,0,0);}condition="OPAQUE EYE OCCLUSION STRESS TEST";}else if(frame>=270&&frame<300){image=rotateImage(image,20);condition="IN-PLANE ROTATION - NOT A 3D YAW TEST";}else if(frame>=300){Image half=resizeImage(base,320,240);image=Image(640,480);paste(image,half,0,120);paste(image,half,320,120);condition="MULTIPLE FACE AMBIGUITY";}camera.write(image);Features f=vision.analyze(image,frame/30.);Decision d=actual.update(f);overlay(image,f,d,30);text(image,8,438,condition,0xffbb33,16);text(image,8,460,"PHOTO TRANSFORMS - NO HUMAN DROWSINESS GROUND TRUTH",0xffbb33,15);observed.write(image);if(frame==240)saveImage(root+"output/occlusion_sample.jpg",image);}
 camera.close();observed.close();Temporal simulated(s);VideoWriter signals(root+"output/temporal_simulation.avi",960,540,30);std::ofstream log(root+"output/temporal_simulation.jsonl");for(int frame=0;frame<600;++frame){double time=frame/30.;Features f=measured(time);if((time>=6&&time<6.15)||(time>=9&&time<11.2))f.leftEar=f.rightEar=.10;if(time>=11.2&&time<14){f.eyesVisible=false;f.reason="Scripted eye occlusion";}Decision d=simulated.update(f);Image image(960,540,24);text(image,12,8,"SCRIPTED FEATURE SIMULATION - NOT CAMERA INFERENCE",0xffbb33,22);ellipse(image,{210,270},{130,170},160,160,160);for(int x:std::vector<int>{165,255})ellipse(image,{double(x),235},{28,f.leftEar<.18?2.:15.},220,220,220);if(!f.eyesVisible)fillRect(image,{125,205,175,65},50,50,50);text(image,380,145,d.state,d.alarm?0xff3030:0xdddddd,23);std::ostringstream line;line<<"time "<<time<<"s | closure "<<d.closureSeconds<<"s";text(image,380,195,line.str());text(image,12,480,d.reason,0xdddddd,18);signals.write(image);log<<"{\"time_s\":"<<time<<",\"state\":"<<jsonString(d.state)<<",\"alarm\":"<<(d.alarm?"true":"false")<<"}\n";}
 signals.close();verifyVideo(root+"testdata/vision_demo_input.avi",360,640,480);verifyVideo(root+"output/vision_demo.avi",360,640,480);verifyVideo(root+"output/temporal_simulation.avi",600,960,540);std::ofstream verified(root+"tests/demo_verification.json");verified<<"{\"status\":\"passed\",\"vision_frames\":360,\"temporal_frames\":600,\"fps\":30,\"all_frames_decoded\":true,\"real_drowsiness_accuracy_measured\":false}\n";std::cout<<"Created and decoded both review videos; photo transforms and scripted features do not measure real drowsiness accuracy\n";return 0;}
